using System.Text;

namespace FibenImport;

/// <summary>
/// The T-SQL scripts of database/fiben/ (decision 149), written after the pattern of
/// database/ldbc/: tables and keys, the bulk load through staging tables of text, and the
/// foreign keys checked once after the load. The {{schema}} placeholder is dbo in the Fiben
/// database of the container; batches are separated by GO.
/// </summary>
public static class Scripts
{
    private const string Header =
        """
        -- Generated by FibenImport from FIBEN.sql of IBM/fiben-benchmark (Apache-2.0); do not edit
        -- by hand - change the tool and run it again. Decision 149.
        """;

    public static string Schema(Ddl ddl)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- The 152 tables of the FIBEN schema (FIBO and FRO concepts as tables) with their primary
            -- keys, every key one BIGINT column. The foreign keys are in constraints.sql, which runs
            -- after load.sql, so that a bulk load is not checked row by row. The types follow the Db2
            -- declarations: BIGINT, INTEGER as INT, DOUBLE PRECISION as FLOAT, DATE, TIMESTAMP as
            -- DATETIME2(6), CHARACTER(5) as CHAR(5) and VARCHAR(1024) as NVARCHAR(1024) - the data
            -- holds names outside ASCII. Every text compares binary, as Db2 compares it. Nothing is
            -- indexed beyond the keys, because the benchmark declares nothing beyond them.
            --
            -- Batches are separated by a line containing only GO; the {{schema}} placeholder is dbo
            -- in the Fiben database of the container.
            """);

        foreach (var table in ddl.Tables)
        {
            text.AppendLine();
            text.AppendLine($"CREATE TABLE [{{{{schema}}}}].[{table.Name}] (");
            foreach (var column in table.Columns)
            {
                text.AppendLine($"    [{column.Name}] {column.SqlType} {(column.NotNull ? "NOT NULL" : "NULL")},");
            }

            text.AppendLine($"    CONSTRAINT [PK_{table.Name}] PRIMARY KEY ([{table.KeyColumn}])");
            text.AppendLine(");");
            text.AppendLine("GO");
        }

        return text.ToString();
    }

    public static string Constraints(Ddl ddl)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- The 159 foreign keys of FIBEN.sql, run after schema.sql and, in the container, after the
            -- data is loaded. They are declared WITH CHECK, so the load is verified once, at the end,
            -- and the constraints are trusted by the optimizer and by the catalog completion phase
            -- alike: the catalog reads relations from exactly these declarations (decision 015). Most
            -- of them share the key column with the referenced table - a FIBO subclass is a table whose
            -- key is the key of its superclass.
            """);

        foreach (var key in ddl.ForeignKeys)
        {
            text.AppendLine();
            text.AppendLine($"ALTER TABLE [{{{{schema}}}}].[{key.Table}] WITH CHECK ADD");
            text.AppendLine($"    CONSTRAINT [{key.Name}] FOREIGN KEY ([{key.Column}]) REFERENCES [{{{{schema}}}}].[{key.ReferencedTable}] ([{key.ReferencedColumn}]);");
            text.AppendLine("GO");
        }

        return text.ToString();
    }

    public static string Load(Ddl ddl)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- Loads data.zip of the benchmark into the tables of schema.sql. Run by sqlcmd between
            -- schema.sql and constraints.sql with one variable, DataPath: the directory data.zip unpacks
            -- to - the one holding one <TABLE>.csv per table - as a path the database server itself can
            -- read, since BULK INSERT runs there.
            --
            -- The files are what Db2 exports "of del": comma-separated, text in double quotes, an empty
            -- field for NULL, a date as yyyymmdd, a timestamp as yyyy-mm-dd-hh.mm.ss.ffffff and a double
            -- with a sign and an exponent (+3.88000000000000E+008); UTF-8 without a header. Most of the
            -- files are empty: 111 of the 152 tables hold no rows. Every file goes into a staging table
            -- of text first and is converted from there, so a malformed value fails with the name of the
            -- table; the staging columns are VARCHAR in a UTF-8 collation and the files are read with
            -- CODEPAGE = 'RAW', the one form SQL Server on Linux accepts. The staging schema is dropped
            -- at the end.
            --
            -- The {{schema}} placeholder works as in schema.sql.

            SET NOCOUNT ON;
            SET XACT_ABORT ON;
            GO

            IF SCHEMA_ID('fiben_load') IS NULL EXEC (N'CREATE SCHEMA [fiben_load]');
            GO
            """);

        foreach (var table in ddl.Tables)
        {
            var staged = string.Join(", ", table.Columns.Select(column => $"[{column.Name}] VARCHAR({(column.IsText ? 1024 : 64)}) COLLATE Latin1_General_100_BIN2_UTF8"));
            text.AppendLine();
            text.AppendLine($"CREATE TABLE [fiben_load].[{table.Name}] ({staged});");
            text.AppendLine($"BULK INSERT [fiben_load].[{table.Name}] FROM '$(DataPath)/{table.Name}.csv' WITH (FORMAT = 'CSV', FIELDQUOTE = '\"', FIELDTERMINATOR = ',', ROWTERMINATOR = '0x0a', CODEPAGE = 'RAW', TABLOCK);");
            text.AppendLine($"INSERT INTO [{{{{schema}}}}].[{table.Name}] WITH (TABLOCK) ({string.Join(", ", table.Columns.Select(column => $"[{column.Name}]"))})");
            text.AppendLine($"SELECT {string.Join(", ", table.Columns.Select(column => column.Conversion($"[{column.Name}]")))}");
            text.AppendLine($"FROM [fiben_load].[{table.Name}];");
            text.AppendLine($"DROP TABLE [fiben_load].[{table.Name}];");
            text.AppendLine("GO");
        }

        text.AppendLine();
        text.AppendLine("DROP SCHEMA [fiben_load];");
        text.AppendLine("GO");

        return text.ToString();
    }

    /// <summary>
    /// The Dapper entity class of one table (decision 149): properties named as the columns are,
    /// typed as the Db2 declaration says, nothing else. A Dapper source states no key, relation
    /// or length; every such fact comes from the catalog of the Fiben database.
    /// </summary>
    public static string Entity(Table table)
    {
        var text = new StringBuilder();
        text.AppendLine("namespace Fiben;");
        text.AppendLine();
        text.AppendLine($"public class {table.Name}");
        text.AppendLine("{");

        var first = true;
        foreach (var column in table.Columns)
        {
            if (!first)
            {
                text.AppendLine();
            }

            first = false;
            text.AppendLine($"    public {column.CSharpType} {column.Name} {{ get; set; }}");
        }

        text.AppendLine("}");
        return text.ToString();
    }
}
